var a=[{title:`Honnan jön a zaj`,text:`Az ismétlődő lábcsapódások, a kötélugrás, a burpee-k, a nehéz landolások, a gördülő felszerelés és a leejtett súlyzók mind hangot visznek át az épületen. A vékony padlók egy kis ütést is hangossá tehetnek. Egy rutin, amely egy földszinti konditeremben csendesnek tűnik, zavarhatja az emeleti lakás alatt lakókat.`},{title:`Csendesebb cserék`,text:`Cseréld a terpeszugrást oldalsó lépésre, az ugróguggolást kontrollált guggolásra, a helyben futást menetelésre, a nagy ütésterhelésű burpee-t pedig hátralépős változatra. Az árnyékbox, a lendületes séta, a helyhez kötött kerékpározás és a kontrollált lépcsőre lépés ismételt kemény landolások nélkül emelheti a légzésedet és a pulzusodat.`},{title:`Javítsd a felállást`,text:`Tiszta, csúszásmentes padlón edzz. Az edzőmatrac csillapíthat némi hangot és védheti a padlót, de nem állíthatja meg a rezgést, amely a szerkezeten át terjed. Tudatosan engedd le a súlyokat, és ne halmozz laza felszerelést. Ellenőrizd, hogy a lépcsőemelvény vagy pad nem billeg és nem dübörög-e minden ismétlésnél.`},{title:`Intenzitás ütésterhelés nélkül`,text:`Az, hogy a kardió mennyire nehéz, az erőfeszítésedtől függ, az ugrás pedig csak az egyik módja a növelésének. A hosszabb intervallumok, a rövidebb, de még mindig regenerálódást engedő pihenők vagy a folyamatos alacsony ütésterhelésű mozgás mind állóképességet építenek. Az erőedzésben a lassú, kontrollált emelések és megállások kemény munkák lehetnek, és csendesek maradnak, ezért nem kell sietned, hogy nehezebbnek érződjön az edzés.`},{title:`A TrainUp használata`,text:`A Profilban az, hogy az ugrás rendben van-e, és az, hogy mennyi zaj elfogadható, két külön beállítás. Ha mindkettőt korlátozod, a terv kihagyja az ugrásokat, a kötélugrást és más dübörgő gyakorlatokat, és csendesebbekkel így is a célod felé edz. Egy matrac önmagában nem teszi csendessé az ugrógyakorlatot.`}];var s=[{label:`CDC: felnőttek fizikai aktivitási ajánlásai`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`},{label:`CDC: az aktivitás intenzitásának mérése és a beszédteszt`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`ACE gyakorlatkönyvtár`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var l={sections:a,sources:s};export{l as default,a as sections,s as sources};